package net.minecraft.world.level.levelgen.synth;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import it.unimi.dsi.fastutil.doubles.*;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.levelgen.PositionalRandomFactory;
import org.junit.jupiter.api.Test;

/** Observable actual RNG/list effects, before any composite constructor migration. */
class CompositeConstructorContractTest {
 static final class Source implements RandomSource {
  final RandomSource actual=RandomSource.create(42);final List<String> calls=new ArrayList<>();final List<String> hashes=new ArrayList<>();Runnable onHash;
  public PositionalRandomFactory forkPositional(){calls.add("forkPositional");var p=actual.forkPositional();return new PositionalRandomFactory(){public RandomSource fromHashOf(String name){hashes.add(name);Runnable action=onHash;if(action!=null){onHash=null;action.run();}return p.fromHashOf(name);}public RandomSource fromSeed(long seed){throw new AssertionError("fromSeed");}public RandomSource at(int x,int y,int z){throw new AssertionError("at");}public void parityConfigString(StringBuilder b){p.parityConfigString(b);}};}
  public RandomSource fork(){throw new AssertionError("fork");}public void setSeed(long seed){throw new AssertionError("setSeed");}
  public int nextInt(){calls.add("int");return actual.nextInt();}public int nextInt(int bound){calls.add("int:"+bound);return actual.nextInt(bound);}public double nextDouble(){calls.add("double");return actual.nextDouble();}public long nextLong(){return actual.nextLong();}
  public void consumeCount(int count){calls.add("consume:"+count);actual.consumeCount(count);}
  public boolean nextBoolean(){throw new AssertionError("boolean");}public float nextFloat(){throw new AssertionError("float");}public double nextGaussian(){throw new AssertionError("gaussian");}
 }
 @Test void zeroModernAmplitudesStillForkTheActualSource(){var s=new Source();var noise=PerlinNoise.create(s,-2,new DoubleArrayList(new double[]{0,-0.0,0}));assertEquals(List.of("forkPositional"),s.calls);assertTrue(s.hashes.isEmpty());assertNull(noise.getOctaveNoise(0));var expected=RandomSource.create(42);expected.forkPositional();assertEquals(expected.nextLong(),s.nextLong());}
 @Test void modernFactoryReceivesOriginalNonzeroOctaveNames(){var s=new Source();PerlinNoise.create(s,-3,new DoubleArrayList(new double[]{1,0,Double.NaN,-0.0,1}));assertEquals(List.of("forkPositional"),s.calls);assertEquals(List.of("octave_-3","octave_-1","octave_1"),s.hashes);}
 @Test void genuineFactoryCallbackChangesALaterAmplitude(){var s=new Source();var amplitudes=new DoubleArrayList(new double[]{1,1,1});s.onHash=()->amplitudes.set(1,0);var noise=PerlinNoise.create(s,-2,amplitudes);assertEquals(List.of("octave_-2","octave_0"),s.hashes);assertNull(noise.getOctaveNoise(1));}
 @Test void listFailureOccursAfterActualForkAndBeforeHash(){var failure=new RuntimeException("actual amplitude");var list=new DoubleArrayList(new double[]{1}){@Override public double getDouble(int index){throw failure;}};var s=new Source();assertSame(failure,assertThrows(RuntimeException.class,()->PerlinNoise.create(s,0,list)));assertEquals(List.of("forkPositional"),s.calls);assertTrue(s.hashes.isEmpty());}
 @Test void legacyZeroLevelsStillConsumeInitialLeafAndSkippedOctaves(){var s=new Source();PerlinNoise.createLegacyForLegacyNetherBiome(s,-2,new DoubleArrayList(new double[]{0,0,0}));assertEquals(261,s.calls.size());assertEquals(List.of("double","double","double"),s.calls.subList(0,3));assertEquals(List.of("consume:262","consume:262"),s.calls.subList(259,261));var expected=RandomSource.create(42);new ImprovedNoise(expected);expected.consumeCount(524);assertEquals(expected.nextLong(),s.nextLong());}
 @Test void legacyValidationPreservesItsOrderAfterInitialLeaf(){for(boolean countMismatch:new boolean[]{false,true}){var s=new Source();var failure=assertThrows(RuntimeException.class,()->PerlinNoise.createLegacyForLegacyNetherBiome(s,0,new DoubleArrayList(countMismatch?new double[]{1,1}:new double[]{1,0})));assertEquals(countMismatch?"Failed to create correct number of noise levels for given non-zero amplitudes":"Positive octaves are temporarily disabled",failure.getMessage());assertEquals(259,s.calls.size());}}
 @Test void emptySimplexOctavesRejectBeforeAnyRngEffect(){var s=new Source();assertEquals("Need some octaves!",assertThrows(IllegalArgumentException.class,()->new PerlinSimplexNoise(s,List.of())).getMessage());assertTrue(s.calls.isEmpty());}
 static java.lang.ref.WeakReference<ImprovedNoise> weakLeaf(PerlinNoise noise){var leaf=noise.getOctaveNoise(0);assertNotNull(leaf);assertSame(leaf,noise.getOctaveNoise(0));return new java.lang.ref.WeakReference<>(leaf);}
 @Test void exposedLeafKeepsItsIdentityAndOriginalParentCustody()throws Exception{var noise=PerlinNoise.create(RandomSource.create(42),-2,new DoubleArrayList(new double[]{1,1,1}));var weak=weakLeaf(noise);for(int i=0;i<12;i++){System.gc();Thread.sleep(10);}assertNotNull(weak.get(),"public octave facade lost its original strong parent custody");assertSame(weak.get(),noise.getOctaveNoise(0));java.lang.ref.Reference.reachabilityFence(noise);}
 @Test void actualFactoryReentryUsesIndependentOuterAndInnerPlans(){var s=new Source();var inner=new ArrayList<PerlinNoise>();s.onHash=()->inner.add(PerlinNoise.create(s,-2,new DoubleArrayList(new double[]{1,1})));var outer=PerlinNoise.create(s,-1,new DoubleArrayList(new double[]{1,1}));assertEquals(List.of("forkPositional","forkPositional"),s.calls);assertEquals(List.of("octave_-1","octave_-2","octave_-1","octave_0"),s.hashes);assertEquals(1,inner.size());assertNotSame(outer.getOctaveNoise(1),inner.get(0).getOctaveNoise(1));}
 @Test void amplitudeCallbackReentryKeepsIndependentMetadataReaders(){var holder=new PerlinNoise[1];boolean[] armed={false};var trace=new ArrayList<Integer>();var values=new DoubleArrayList(new double[]{1,.5,1}){@Override public double getDouble(int index){trace.add(index);if(armed[0]){armed[0]=false;holder[0].maxBrokenValue(.5);}return super.getDouble(index);}};holder[0]=PerlinNoise.create(RandomSource.create(42),-2,values);double expected=holder[0].maxBrokenValue(.5);trace.clear();armed[0]=true;assertEquals(Double.doubleToRawLongBits(expected),Double.doubleToRawLongBits(holder[0].maxBrokenValue(.5)));assertEquals(List.of(0,0,1,2,1,2),trace);}
 @Test void emptyPerlinOctavesRejectBeforeAnyRngEffect(){var source=new Source();assertEquals("Need some octaves!",assertThrows(IllegalArgumentException.class,()->PerlinNoise.create(source,List.of())).getMessage());assertTrue(source.calls.isEmpty());}
 @Test void overflowedOctaveSpanRejectsBeforeAnyRngEffect(){var source=new Source();assertEquals("Total number of octaves needs to be >= 1",assertThrows(IllegalArgumentException.class,()->PerlinNoise.create(source,List.of(Integer.MIN_VALUE,Integer.MAX_VALUE))).getMessage());assertTrue(source.calls.isEmpty());}
 @Test void unsortedDuplicateOctavesPreserveCanonicalFactoryOrder(){var source=new Source();var noise=PerlinNoise.create(source,List.of(0,-3,0,-3));assertEquals(List.of("octave_-3","octave_0"),source.hashes);assertEquals(List.of("forkPositional"),source.calls);assertNotNull(noise.getOctaveNoise(0));assertNull(noise.getOctaveNoise(1));assertNull(noise.getOctaveNoise(2));assertNotNull(noise.getOctaveNoise(3));}
}
